import { getTranslations, translate, Language, languages } from '@/lib/translations';

export function generateStaticParams() {
  return languages.map((lang) => ({ lang }));
}

interface ExportProps {
  params: Promise<{ lang: Language }>;
}

export default async function Export({ params }: ExportProps) {
  const { lang } = await params;
  const translations = getTranslations(lang);
  const t = (key: string, params?: Record<string, string>) => 
    translate(translations, key, params);

  return (
    <main className="container mx-auto px-4 py-12">
      <div className="max-w-4xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-900 mb-8">{t('export.title')}</h1>
        <div className="prose prose-lg max-w-none">
          <p className="text-lg text-gray-700 mb-4">
            {t('export.description1')}
          </p>
          <p className="text-lg text-gray-700 mb-4">
            {t('export.description2')}
          </p>
          <ul className="list-disc list-inside text-lg text-gray-700 space-y-2 mb-4">
            <li>{t('export.services.compliance')}</li>
            <li>{t('export.services.logistics')}</li>
            <li>{t('export.services.packaging')}</li>
            <li>{t('export.services.documentation')}</li>
          </ul>
          <p className="text-lg text-gray-700">
            {t('export.inquiry')}
          </p>
        </div>
      </div>
    </main>
  );
}

